#include <bits/stdc++.h>
using namespace std;
int main(){
    string rows[4] = {"`1234567890-=", "QWERTYUIOP[]\\","ASDFGHJKL;'", "ZXCVBNM,./"};
    map<char,char> shift;
    for (auto &r : rows) for (size_t i=1;i<r.size();i++) shift[r[i]] = r[i-1];
    string line;
    while (getline(cin,line)) {
        string out;
        for (char c : line) out += shift.count(c) ? shift[c] : c;
        cout << out << "\n";
    }
}

