#include <bits/stdc++.h>
using namespace std;
int main(){
    string rows[4] = {"`1234567890-=", "QWERTYUIOP[]\\","ASDFGHJKL;'", "ZXCVBNM,./"};
    map<char,char> shift;
    for (auto &r : rows) for (size_t i=1;i<r.size();i++) shift[r[i]] = r[i-1];
    string word;
    bool first = true;
    while (cin >> word) {
        if (!first) cout << " ";
        first = false;
        for (char c : word) cout << (shift.count(c) ? shift[c] : c);
    }
    cout << "\n";
}
